import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Macro-Settings.md","filePath":"manual-zh/Macro-Settings.md","lastUpdated":1785684581000}'),n={name:"manual-zh/Macro-Settings.md"};function E(T,a,S,s,c,i){return t(),o("div",null,[...a[0]||(a[0]=[r('<h4 id="_14-2-11-macro-settings" tabindex="-1">14.2.11 Macro Settings <a class="header-anchor" href="#_14-2-11-macro-settings" aria-label="Permalink to &quot;14.2.11 Macro Settings&quot;">​</a></h4><p>某些宏行为通过 SET 命令控制（参见 <a href="./SET">SET</a>）。本节描述这些设置。</p><p>在宏主体内更改这些设置的任何 SET 命令仅在宏之后生效。这是因为 PSPP 一次性展开宏的整个主体，因此主体内的 SET 命令只在之后才执行。</p><p>MEXPAND 设置（参见 <a href="./SET#SET-MEXPAND">SET MEXPAND</a>）控制是否展开宏。默认情况下，宏展开是开启的。要避免展开宏主体内调用的宏，请使用 <code>!OFFEXPAND</code> 和 <code>!ONEXPAND</code>（参见 <a href="./Controlling-Macro-Expansion">Controlling Macro Expansion</a>）。</p><p>当 MPRINT（参见 <a href="./SET#SET-MPRINT">SET MPRINT</a>）开启时，PSPP 输出每个被调用宏的展开。此功能对调试宏定义很有用。要阅读展开后的版本，请注意宏展开会移除注释并标准化空白。</p><p>MNEST（参见 <a href="./SET#SET-MNEST">SET MNEST</a>）限制宏调用展开的深度，即宏展开的嵌套层级。默认值为 50。这主要用于避免自调用宏的无限展开。</p><p>MITERATE（参见 <a href="./SET#SET-MITERATE">SET MITERATE</a>）限制 <code>!DO</code> 结构中的迭代次数。默认值为 1000。</p>',7)])])}const d=e(n,[["render",E]]);export{_ as __pageData,d as default};
